#pragma once
// compiled-in ore features and their placement rules: the dedicated server's feature / feature_rules data (the ore_feature kind), biome filters already
// evaluated against bedrock-samples' biome tags. generated by tools/gen_features.py
#include <cstdint>

namespace perlin::server::vanilla {

    struct OreReplaceDef {
        const char* place;
        const char* mayReplace0;
        const char* mayReplace1;
    };

    struct OreFeatureDef {
        const char* name;
        int count;
        float discardChanceOnAirExposure;
        int replaceCount;
        OreReplaceDef replace[2];
    };

    // kind 0 uniform, 1 triangle, 2 a constant (lo); x and z give lo <= v < hi, y gives lo <= v <= hi
    struct DistDef {
        int kind;
        int lo;
        int hi;
    };

    struct OreRuleDef {
        const char* name;
        int feature;
        // 0 before_underground_pass, 1 underground_pass, 2 after_surface_pass
        int pass;
        int iterations;
        DistDef x, y, z;
        // the order the three coordinates are drawn in, e.g. "zyx"
        const char* order;
        int scatterNumerator, scatterDenominator;
        // bit i is set when biome i of the server's table passes the rule's biome filter
        uint64_t biomeMask[2];
    };

    extern const int kOreFeatureCount;
    extern const OreFeatureDef kOreFeatures[];
    extern const int kOreRuleCount;
    extern const OreRuleDef kOreRules[];
}
